package org.sleepwell.app;
import java.time.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.*;
/** Reviewed elapsed-duration proposal converted explicitly to the app's whole-minute local alarm. */
final class RelativeAlarmTime {
 final int minutes;final long wall,elapsed,requested,target;final ZoneId zone;final ZonedDateTime local;
 RelativeAlarmTime(int minutes,long wall,long elapsed,ZoneId zone){if(minutes<1||minutes>1440||wall<0||elapsed<0||zone==null)throw new IllegalArgumentException("Choose 1 minute to 24 hours.");this.minutes=minutes;this.wall=wall;this.elapsed=elapsed;this.zone=zone;try{requested=Math.addExact(wall,minutes*60000L);long ceil=Math.addExact(Math.floorDiv(requested,60000)*60000L,requested%60000==0?0:60000L);target=ceil-wall<=86400000L?ceil:Math.floorDiv(requested,60000)*60000L;local=Instant.ofEpochMilli(target).atZone(zone);if(target<=wall||target-wall>86400000L||zone.getRules().getValidOffsets(local.toLocalDateTime()).size()!=1||AlarmDate.at(local.toLocalDate(),local.getHour(),local.getMinute(),zone)!=target)throw new IllegalArgumentException("This local time repeats during a clock change. Choose another duration.");}catch(ArithmeticException|DateTimeException invalid){throw new IllegalArgumentException("This relative time cannot be represented.");}}
 void check(long now,long nowElapsed,ZoneId nowZone){long drift;try{drift=Math.subtractExact(Math.subtractExact(now,wall),Math.subtractExact(nowElapsed,elapsed));}catch(ArithmeticException invalid){throw new IllegalArgumentException("Phone time changed. Review a new proposal.");}if(nowElapsed<elapsed||(drift>2000||drift< -2000)||!zone.equals(nowZone))throw new IllegalArgumentException("Phone time or zone changed. Review a new proposal.");if(target<=now)throw new IllegalArgumentException("This proposed time passed. Review a new proposal.");}
 String rounding(){long difference=target-requested;if(difference==0)return "Exact whole-minute target.";return "Whole-minute alarm: rounded "+(difference>0?"up":"down")+" by "+((Math.abs(difference)+999)/1000)+" seconds"+(difference<0?" to stay within 24 hours.":".");}
 boolean clockChanges(){return !Instant.ofEpochMilli(wall).atZone(zone).getOffset().equals(local.getOffset());}
 static boolean allowed(Alarm a){return a!=null&&a.nap==null&&!a.napInvalid&&a.solar==null&&!a.solarInvalid&&a.days.isEmpty();}
 static String identity(Alarm a){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(a.json().toString().getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
}
